PRAGMA foreign_keys=ON;
CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,username TEXT UNIQUE NOT NULL,display_name TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'member' CHECK(role IN ('member','admin')),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')),private INTEGER NOT NULL DEFAULT 0,email_verified INTEGER NOT NULL DEFAULT 0,bio TEXT NOT NULL DEFAULT '',lock_until INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL);
CREATE TABLE email_tokens(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,purpose TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE media(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,mime TEXT NOT NULL,size INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE posts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,media_id TEXT NOT NULL UNIQUE REFERENCES media(id),caption TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('photo','reel','video','story')),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','removed')),human_declared INTEGER NOT NULL,expires_at INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE follows(follower TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,following TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,accepted INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(follower,following),CHECK(follower<>following));
CREATE TABLE blocks(blocker TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,blocked TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(blocker,blocked),CHECK(blocker<>blocked));
CREATE TABLE likes(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,PRIMARY KEY(user_id,post_id));
CREATE TABLE saves(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,PRIMARY KEY(user_id,post_id));
CREATE TABLE comments(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,body TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE messages(id TEXT PRIMARY KEY,sender TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,recipient TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,body TEXT NOT NULL,created_at INTEGER NOT NULL,CHECK(sender<>recipient));
CREATE TABLE reports(id TEXT PRIMARY KEY,reporter TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at INTEGER NOT NULL,UNIQUE(reporter,post_id));
CREATE TABLE audit(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE products(id TEXT PRIMARY KEY,name TEXT NOT NULL,brand TEXT NOT NULL,price_cents INTEGER NOT NULL CHECK(price_cents>0),url TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL);
CREATE INDEX feed_order ON posts(status,created_at DESC);
CREATE INDEX posts_owner ON posts(user_id,created_at DESC);
CREATE INDEX message_thread ON messages(sender,recipient,created_at DESC);
CREATE INDEX message_inbox ON messages(recipient,created_at DESC);
CREATE INDEX session_owner ON sessions(user_id);
